public int minInsertions(String s) {
    int open = 0; // Number of open parentheses needed to balance
    int inserts = 0; // Number of insertions made

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            open += 2; // Each '(' needs two ')' to potentially balance
            // If there's an odd number of ')' needed, we need to insert one
            if (open % 2 == 1) {
                inserts++;
                open--; // This '(' will balance one of the ')'
            }
        } else { // s.charAt(i) == ')'
            open--; // We have a ')', so we need one less '('
            if (open == -1) {
                inserts++; // We need to insert a '(' to balance this ')'
                open = 1; // We need one more ')' now
            }
        }
    }

    // At the end, open might still be positive if there are unmatched '('
    inserts += open;

    return inserts;
}

