public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remaining = k - n;
    for (int i = 0; i < n; i++) {
        if (remaining >= 25) {
            result.append('z');
            remaining -= 25;
        } else {
            result.append((char) ('a' + remaining));
            remaining = 0;
        }
    }
    return result.reverse().toString();
}

